using namespace std;

int main() {
    // 1. Variáveis: a pontos já está pronta; crie vidas e combustivel
    int pontos = 0;

    // 2. Estrelas: some 4 * 25 aos pontos com +=

    // 3. Asteroide: tire 1 de vidas

    // 4. Portal: dobre os pontos com *=

    // 5. Saltos: tire 3 * 12.5 do combustivel com -=

    // 6. Mostre pontos, vidas e combustivel

    return 0;
}

cpp2m1.solucao:
#include <iostream>
using namespace std;

int main() {
    int pontos = 0;
    int vidas = 3;
    double combustivel = 80.0;

    pontos += 4 * 25;         // 4 estrelas de 25 pontos
    vidas -= 1;               // o asteroide tira uma vida
    pontos *= 2;              // o portal dobra os pontos
    combustivel -= 3 * 12.5;  // 3 saltos de 12.5

    cout << "Pontos: " << pontos << endl;
    cout << "Vidas: " << vidas << endl;
    cout << "Combustível: " << combustivel << endl;
    return 0;
}

