#include <iostream>
#include <string>
using namespace std;

int main() {
    string nome, textoPontos, textoPartidas;

    cout << "Jogador: ";
    getline(cin, nome);
    cout << "Pontos: ";
    getline(cin, textoPontos);
    int pontos = stoi(textoPontos);
    cout << "Partidas: ";
    getline(cin, textoPartidas);
    int partidas = stoi(textoPartidas);

    cout << "Média inteira: " << pontos / partidas << endl;
    cout << "Média exata: " << static_cast<double>(pontos) / partidas << endl;

    string resumo = nome + " fez " + to_string(pontos) + " pontos em " + to_string(partidas) + " partidas";
    cout << "Resumo: " << resumo << endl;
    return 0;
}

