#include <iomanip>
using namespace std;

int main() {
    const double DESCONTO = 0.10;
    double preco = 0;
    int parcelas = 0;

    cout << "Preço do jogo: ";
    cin >> preco;
    cout << "Parcelas: ";
    cin >> parcelas;

    auto avista = preco * (1 - DESCONTO);
    auto parcela = preco / parcelas;

    cout << fixed << setprecision(2);
    cout << "Preço: R$ " << preco << endl;
    cout << "À vista (10% de desconto): R$ " << avista << endl;
    cout << "Parcelado: " << parcelas << "x de R$ " << parcela << endl;
    return 0;
}

