    // 7. Mostre o boletim

    return 0;
}

cpp2m6.solucao:
#include <iostream>
#include <iomanip>
#include <string>
using namespace std;

int main() {
    const double ZERO_ABSOLUTO = 273.15;
    string estacao;
    double minima = 0;
    double maxima = 0;

    cout << "Estação: ";
    getline(cin, estacao);
    cout << "Mínima (°C): ";
    cin >> minima;
    cout << "Máxima (°C): ";
    cin >> maxima;

    double minimaF = minima * 9 / 5 + 32;
    double maximaF = maxima * 9 / 5 + 32;
    double minimaK = minima + ZERO_ABSOLUTO;
    double maximaK = maxima + ZERO_ABSOLUTO;
    double media = (minima + maxima) / 2;
    double variacao = maxima - minima;

    cout << fixed << setprecision(2);
    cout << "=== Boletim: " << estacao << " ===" << endl;
    cout << "Mínima: " << minima << " °C | " << minimaF << " °F | " << minimaK << " K" << endl;
    cout << "Máxima: " << maxima << " °C | " << maximaF << " °F | " << maximaK << " K" << endl;
    cout << "Média do dia: " << media << " °C" << endl;
    cout << "Variação: " << variacao << " °C" << endl;
    return 0;
}

